import { readFileSync } from 'node:fs'

const fail = (msg) => { process.stderr.write(`error: ${msg}\n`); process.exit(2) }

function parse(s) {
  const r = { scheme: undefined, auth: undefined, path: '', query: undefined, fragment: undefined }
  let m = /^([^:/?#]+):/.exec(s)
  if (m) { r.scheme = m[1]; s = s.slice(m[0].length) }
  const h = s.indexOf('#')
  if (h >= 0) { r.fragment = s.slice(h + 1); s = s.slice(0, h) }
  const q = s.indexOf('?')
  if (q >= 0) { r.query = s.slice(q + 1); s = s.slice(0, q) }
  if (s.startsWith('//')) {
    s = s.slice(2)
    const e = s.search(/\//)
    r.auth = e >= 0 ? s.slice(0, e) : s
    s = e >= 0 ? s.slice(e) : ''
  }
  r.path = s
  return r
}

function splitAuth(a) {
  const at = a.lastIndexOf('@')
  const userinfo = at >= 0 ? a.slice(0, at) : undefined
  const hp = a.slice(at + 1)
  const c = hp.indexOf(':', Math.max(hp.lastIndexOf(']'), 0))
  return c >= 0 ? { userinfo, host: hp.slice(0, c), port: hp.slice(c + 1) } : { userinfo, host: hp, port: undefined }
}

function removeDots(p) {
  let out = ''
  while (p.length) {
    if (p.startsWith('../')) p = p.slice(3)
    else if (p.startsWith('./')) p = p.slice(2)
    else if (p.startsWith('/./')) p = p.slice(2)
    else if (p === '/.') p = '/'
    else if (p.startsWith('/../') || p === '/..') {
      p = p === '/..' ? '/' : p.slice(3)
      out = out.slice(0, Math.max(out.lastIndexOf('/'), 0))
    } else if (p === '.' || p === '..') p = ''
    else {
      const i = p.indexOf('/', 1)
      const seg = i >= 0 ? p.slice(0, i) : p
      out += seg
      p = p.slice(seg.length)
    }
  }
  return out
}

const lower = (s) => s.replace(/[A-Z]/g, (c) => c.toLowerCase())
const UNRES = /^[A-Za-z0-9\-._~]$/
const pct = (s) => s.replace(/%([0-9A-Fa-f]{2})/g, (_, h) => {
  const c = String.fromCharCode(parseInt(h, 16))
  return UNRES.test(c) ? c : '%' + h.toUpperCase()
})
const bad = (s) => s !== undefined && /%(?![0-9A-Fa-f]{2})/.test(s)
const DEFAULT = { http: '80', ws: '80', https: '443', wss: '443', ftp: '21' }

function normalize(r, n) {
  let ui, host, port
  if (r.auth !== undefined) ({ userinfo: ui, host, port } = splitAuth(r.auth))
  const checks = [['path', r.path], ['userinfo', ui], ['host', host], ['query', r.query], ['fragment', r.fragment]]
  for (const [name, v] of checks) if (bad(v)) fail(`line ${n}: the ${name} has a truncated percent-encoding`)
  const scheme = r.scheme === undefined ? undefined : lower(r.scheme)
  let out = ''
  if (scheme !== undefined) out += scheme + ':'
  let path = pct(r.path)
  if (r.auth !== undefined) {
    if (port === '' || (scheme && DEFAULT[scheme] === port)) port = undefined
    out += '//' + (ui !== undefined ? pct(ui) + '@' : '') + lower(pct(host)) + (port !== undefined ? ':' + pct(port) : '')
  }
  path = removeDots(path)
  if (r.auth !== undefined && path === '') path = '/'
  out += path
  if (r.query !== undefined) out += '?' + pct(r.query)
  if (r.fragment !== undefined) out += '#' + pct(r.fragment)
  return out
}

function resolve(base, ref) {
  const t = {}
  if (ref.scheme !== undefined) return { ...ref, path: removeDots(ref.path) }
  t.scheme = base.scheme
  if (ref.auth !== undefined) return { ...ref, scheme: base.scheme, path: removeDots(ref.path) }
  t.auth = base.auth
  if (ref.path === '') {
    t.path = base.path
    t.query = ref.query !== undefined ? ref.query : base.query
  } else {
    if (ref.path.startsWith('/')) t.path = removeDots(ref.path)
    else {
      let m
      if (base.auth !== undefined && base.path === '') m = '/' + ref.path
      else { const i = base.path.lastIndexOf('/'); m = base.path.slice(0, i + 1) + ref.path }
      t.path = removeDots(m)
    }
    t.query = ref.query
  }
  t.fragment = ref.fragment
  return t
}

const mode = process.argv.slice(2)
if (mode.length !== 1 || (mode[0] !== 'normalize' && mode[0] !== 'resolve')) fail('usage: cli.js normalize|resolve')
const lines = readFileSync(0, 'utf8').split('\n')
if (lines[lines.length - 1] === '') lines.pop()
const out = []
lines.forEach((line, i) => {
  const n = i + 1
  if (mode[0] === 'normalize') return out.push(normalize(parse(line), n))
  const sp = line.indexOf(' ')
  if (sp < 0) fail(`line ${n}: expected a base and a reference`)
  const base = parse(line.slice(0, sp))
  if (base.scheme === undefined) fail(`line ${n}: the base has no scheme`)
  out.push(normalize(resolve(base, parse(line.slice(sp + 1))), n))
})
process.stdout.write(out.map((l) => l + '\n').join(''))
EOF
