{"command":"cat package.json; mkdir -p src; cat > src/cli.js <<'EOF'
import { readFileSync } from 'node:fs'
import { parseDocument, ParseError } from './parser.js'
import { toJson, toKeys } from './output.js'

const args = process.argv.slice(2)
if (args.length !== 1 || (args[0] !== 'json' && args[0] !== 'keys')) {
  process.stderr.write('error: usage: cli.js json|keys\n')
  process.exit(2)
}
const text = readFileSync(0, 'utf8')
let root
try {
  root = parseDocument(text)
} catch (e) {
  if (e instanceof ParseError) {
    process.stderr.write(`error: line ${e.line}: ${e.message}\n`)
    process.exit(2)
  }
  throw e
}
process.stdout.write(args[0] === 'json' ? toJson(root) : toKeys(root))
EOF
cat > src/output.js <<'EOF'
function cmp(a, b) {
  const x = Array.from(a, (c) => c.codePointAt(0))
  const y = Array.from(b, (c) => c.codePointAt(0))
  for (let i = 0; i < x.length && i < y.length; i++) if (x[i] !== y[i]) return x[i] - y[i]
  return x.length - y.length
}
const sortedKeys = (t) => [...t.m.keys()].sort(cmp)

function scalar(n) {
  if (n.k === 'integer') return BigInt(n.v).toString()
  return JSON.stringify(n.v)
}

function ser(n, ind) {
  if (n.k === 'table') {
    const ks = sortedKeys(n)
    if (!ks.length) return '{}'
    const pad = '  '.repeat(ind + 1)
    return '{\n' + ks.map((k) => pad + JSON.stringify(k) + ': ' + ser(n.m.get(k), ind + 1)).join(',\n') + '\n' + '  '.repeat(ind) + '}'
  }
  if (n.k === 'array') {
    if (!n.a.length) return '[]'
    const pad = '  '.repeat(ind + 1)
    return '[\n' + n.a.map((x) => pad + ser(x, ind + 1)).join(',\n') + '\n' + '  '.repeat(ind) + ']'
  }
  return scalar(n)
}

export function toJson(root) {
  return ser(root, 0) + '\n'
}

export function toKeys(root) {
  const out = []
  const walk = (n, path) => {
    if (n.k === 'table') {
      for (const k of sortedKeys(n)) {
        const p = path === null ? k : path + '.' + k
        out.push(p + ' ' + n.m.get(k).k)
        walk(n.m.get(k), p)
      }
    } else if (n.k === 'array') {
      n.a.forEach((x, i) => {
        const p = path + '[' + i + ']'
        out.push(p + ' ' + x.k)
        walk(x, p)
      })
    }
  }
  walk(root, null)
  return out.map((l) => l + '\n').join('')
}
EOF
cat > src/parser.js <<'EOF'
export class ParseError extends Error {
  constructor(message, line) {
    super(message)
    this.line = line
  }
}

const table = () => ({ k: 'table', m: new Map(), hdr: false })
const NAME = /[A-Za-z0-9_-]/
const INT = /^[+-]?[0-9]+(_[0-9]+)*$/
const FLOAT = /^[+-]?[0-9]+(_[0-9]+)*(\.[0-9]+(_[0-9]+)*)?([eE][+-]?[0-9]+(_[0-9]+)*)?$/

function fail(msg) {
  throw new ParseError(msg, 0)
}

class Line {
  constructor(s) {
    this.s = s
    this.i = 0
  }
  ws() {
    while (this.s[this.i] === ' ' || this.s[this.i] === '\t') this.i++
  }
  get ch() {
    return this.s[this.i]
  }
  atEnd() {
    this.ws()
    return this.i >= this.s.length || this.ch === '#' || this.ch === ';'
  }

  basic() {
    // at opening quote
    this.i++
    let out = ''
    for (;;) {
      if (this.i >= this.s.length) fail('unterminated string')
      const c = this.s[this.i++]
      if (c === '"') return out
      if (c !== '\\') {
        out += c
        continue
      }
      if (this.i >= this.s.length) fail('unterminated string')
      const e = this.s[this.i++]
      if (e === '"') out += '"'
      else if (e === '\\') out += '\\'
      else if (e === 'n') out += '\n'
      else if (e === 't') out += '\t'
      else if (e === 'r') out += '\r'
      else if (e === '0') out += '\0'
      else if (e === 'u') {
        const h = this.s.slice(this.i, this.i + 4)
        if (!/^[0-9A-Fa-f]{4}$/.test(h)) fail('invalid escape \\u')
        out += String.fromCharCode(parseInt(h, 16))
        this.i += 4
      } else {
        const cp = String.fromCodePoint(this.s.codePointAt(this.i - 1))
        fail('invalid escape \\' + cp)
      }
    }
  }
  literal() {
    const j = this.s.indexOf("'", this.i + 1)
    if (j < 0) fail('unterminated string')
    const v = this.s.slice(this.i + 1, j)
    this.i = j + 1
    return v
  }
  name() {
    this.ws()
    const c = this.ch
    if (c === '"') return this.basic()
    if (c === "'") return this.literal()
    const st = this.i
    while (this.i < this.s.length && NAME.test(this.s[this.i])) this.i++
    if (st === this.i) fail('expected a name')
    return this.s.slice(st, this.i)
  }
  dotted() {
    const names = [this.name()]
    for (;;) {
      this.ws()
      if (this.ch !== '.') return names
      this.i++
      names.push(this.name())
    }
  }

  value(base) {
    this.ws()
    const c = this.ch
    if (this.atEnd() || c === ',' || c === ']' || c === '}') fail('expected a value')
    if (c === '"') return { k: 'string', v: this.basic() }
    if (c === "'") return { k: 'string', v: this.literal() }
    if (c === '[') return this.array(base)
    if (c === '{') return this.inline(base)
    const st = this.i
    while (this.i < this.s.length && !' \t,]}'.includes(this.s[this.i])) this.i++
    const w = this.s.slice(st, this.i)
    if (w === 'true') return { k: 'boolean', v: true }
    if (w === 'false') return { k: 'boolean', v: false }
    if (INT.test(w)) return { k: 'integer', v: w.replace(/_/g, '').replace(/^\+/, '') }
    if (FLOAT.test(w)) return { k: 'float', v: Number(w.replace(/_/g, '')) }
    fail('invalid value ' + w)
  }

  array(base) {
    this.i++
    const a = []
