import { readFileSync } from 'node:fs'

const NAME = /^[A-Za-z0-9_.\/:-]+$/
const COUNT = /^(0|[1-9][0-9]*)$/

class Fail extends Error {}

function parse(text) {
  const policies = new Map()
  const routes = new Map()
  const events = []
  let lastTick = null
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i].trim()
    if (line === '' || line.startsWith('#')) continue
    const t = line.split(/\s+/)
    const fail = (r) => new Fail(`error: line ${i + 1}: ${r}`)
    const num = (v, field, least) => {
      if (!COUNT.test(v) || BigInt(v) < BigInt(least)) throw fail(`${field} must be an integer of at least ${least}`)
      return BigInt(v)
    }
    const d = t[0]
    const decl = () => {
      if (events.length) throw fail('declarations must come before the first event')
    }
    if (d === 'bucket' || d === 'window') {
      const bucket = d === 'bucket'
      const n = bucket ? 5 : 4
      if (t.length !== n) throw fail(bucket ? 'expected bucket <name> <capacity> <refill> <per>' : 'expected window <name> <limit> <span>')
      decl()
      if (!NAME.test(t[1])) throw fail(`invalid policy name ${t[1]}`)
      let p
      if (bucket) p = { kind: 'bucket', name: t[1], cap: num(t[2], 'capacity', 1), refill: num(t[3], 'refill', 0), per: num(t[4], 'per', 1) }
      else p = { kind: 'window', name: t[1], limit: num(t[2], 'limit', 0), span: num(t[3], 'span', 1) }
      if (policies.has(p.name)) throw fail(`policy ${p.name} is declared twice`)
      policies.set(p.name, p)
    } else if (d === 'route') {
      if (t.length < 3) throw fail('expected route <prefix> <policy>...')
      decl()
      if (!NAME.test(t[1])) throw fail(`invalid route prefix ${t[1]}`)
      if (routes.has(t[1])) throw fail(`prefix ${t[1]} is routed twice`)
      for (const p of t.slice(2)) if (!policies.has(p)) throw fail(`unknown policy ${p}`)
      routes.set(t[1], t.slice(2).map((p) => policies.get(p)))
    } else if (d === 'event') {
      if (t.length !== 3) throw fail('expected event <tick> <key>')
      const tick = num(t[1], 'tick', 0)
      if (!NAME.test(t[2])) throw fail(`invalid key ${t[2]}`)
      if (lastTick !== null && tick < lastTick) throw fail(`tick ${tick} is before tick ${lastTick}`)
      lastTick = tick
      events.push({ tick, key: t[2] })
    } else throw fail(`unknown directive ${d}`)
  }
  return { routes, events }
}

function run(mode, text) {
  const { routes, events } = parse(text)
  const states = new Map()
  const stateOf = (p, key) => {
    const id = p.name + '\0' + key
    let s = states.get(id)
    if (!s) {
      s = p.kind === 'bucket' ? { last: null, tokens: p.cap * p.per } : { ticks: [] }
      states.set(id, s)
    }
    return s
  }
  const out = []
  const stats = new Map()
  let ta = 0, td = 0
  for (const ev of events) {
    let route = null, best = -1
    for (const [prefix, ps] of routes) if (ev.key.startsWith(prefix) && prefix.length > best) { best = prefix.length; route = ps }
    let denier = null
    if (route) {
      for (const p of route) {
        const s = stateOf(p, ev.key)
        if (p.kind === 'bucket') {
          if (s.last !== null) {
            s.tokens += p.refill * (ev.tick - s.last)
            if (s.tokens > p.cap * p.per) s.tokens = p.cap * p.per
          }
          s.last = ev.tick
        } else {
          const cut = ev.tick - p.span
          s.ticks = s.ticks.filter((x) => x > cut)
        }
      }
      for (const p of route) {
        const s = stateOf(p, ev.key)
        const ok = p.kind === 'bucket' ? s.tokens >= p.per : BigInt(s.ticks.length) < p.limit
        if (!ok) { denier = p; break }
      }
      if (!denier) {
        for (const p of route) {
          const s = stateOf(p, ev.key)
          if (p.kind === 'bucket') s.tokens -= p.per
          else s.ticks.push(ev.tick)
        }
      }
    }
    const st = stats.get(ev.key) || { a: 0, d: 0 }
    stats.set(ev.key, st)
    if (denier) { st.d++; td++; out.push(`${ev.tick} ${ev.key} deny ${denier.name}`) }
    else { st.a++; ta++; out.push(`${ev.tick} ${ev.key} allow`) }
  }
  if (mode === 'replay') return out
  const res = [...stats.keys()].sort((a, b) => (a < b ? -1 : a > b ? 1 : 0)).map((k) => `${k} allowed=${stats.get(k).a} denied=${stats.get(k).d}`)
  res.push(`total allowed=${ta} denied=${td}`)
  return res
}

const args = process.argv.slice(2)
if (args.length !== 1 || (args[0] !== 'replay' && args[0] !== 'summary')) {
  process.stderr.write('error: usage: cli.js replay|summary\n')
  process.exit(2)
}
try {
  const lines = run(args[0], readFileSync(0, 'utf8'))
  process.stdout.write(lines.map((l) => l + '\n').join(''))
} catch (e) {
  if (!(e instanceof Fail)) throw e
  process.stderr.write(e.message + '\n')
  process.exit(2)
}
