      l = { n: 'bin', op, l, r: add() }
    }
    return l
  }
  function add() {
    let l = mul()
    while (isOp('+') || isOp('-')) { const op = toks[p++].v; l = { n: 'bin', op, l, r: mul() } }
    return l
  }
  function mul() {
    let l = pow()
    while (isOp('*') || isOp('/')) { const op = toks[p++].v; l = { n: 'bin', op, l, r: pow() } }
    return l
  }
  function pow() {
    const l = unary()
    if (isOp('^')) { p++; return { n: 'bin', op: '^', l, r: pow() } }
    return l
  }
  function unary() {
    if (isOp('-') || isOp('+')) { const op = toks[p++].v; return { n: 'un', op, e: unary() } }
    return primary()
  }
  function primary() {
    if (p >= toks.length) bad()
    const t = toks[p++]
    if (t.k === 'num') return { n: 'num', v: t.v }
    if (t.k === 'op') {
      if (t.v === '(') {
        const e = cmp()
        if (!isOp(')')) bad()
        p++
