  let direct = 0
  const bad = () => { throw new Error('grammar') }
  const isOp = (v) => p < toks.length && toks[p].k === 'op' && toks[p].v === v
  function cmp() {
    let l = add()
    while (p < toks.length && toks[p].k === 'op' && ['=', '<>', '<', '<=', '>', '>='].includes(toks[p].v)) {
      const op = toks[p++].v
      l = { n: 'bin', op, l, r: add() }
    }
    return l
  }
  function add() {
    let l = mul()
    while (isOp('+') || isOp('-')) { const op = toks[p++].v; l = { n: 'bin', op, l, r: mul() } }
    return l
  }
  function mul() {
    let l = pow()
    while (isOp('*') || isOp('/')) { const op = toks[p++].v; l = { n: 'bin', op, l, r: pow() } }
    return l
  }
  function pow() {
    const l = unary()
    if (isOp('^')) { p++; return { n: 'bin', op: '^', l, r: pow() } }
    return l
  }
  function unary() {
    if (isOp('-') || isOp('+')) { const op = toks[p++].v; return { n: 'un', op, e: unary() } }
    return primary()
  }
  function primary() {
    if (p >= toks.length) bad()
    const t = toks[p++]
    if (t.k === 'num') return { n: 'num', v: t.v }
    if (t.k === 'op') {
      if (t.v === '(') {
        const e = cmp()
        if (!isOp(')')) bad()
        p++
        return { n: 'paren', e }
      }
      bad()
    }
    const name = t.v.toUpperCase()
    if (isOp('(')) {
      p++
      const args = []
      if (isOp(')')) p++
      else {
        for (;;) {
          const a = cmp()
          if (a.n === 'range') direct++
          args.push(a)
          if (isOp(',')) { p++; continue }
          if (isOp(')')) { p++; break }
          bad()
        }
      }
      return { n: 'call', name, args }
    }
    if (isOp(':')) {
      p++
      if (p >= toks.length || toks[p].k !== 'word') bad()
      ranges++
      return { n: 'range', a: t.v, b: toks[p++].v }
    }
    if (name === 'TRUE') return { n: 'bool', v: true }
    if (name === 'FALSE') return { n: 'bool', v: false }
    return { n: 'ref', a: t.v }
  }
  try {
    const e = cmp()
    if (p !== toks.length) bad()
    return { tree: e, misplaced: ranges !== direct }
  } catch (e) {
    if (e.message === 'grammar') return null
    throw e
  }
}

// ---------- deps ----------
function refsOf(node, out) {
  switch (node.n) {
    case 'ref': { const a = parseAddr(node.a); if (a) out.set(key(a.col, a.row), a); break }
    case 'range': {
      const a = parseAddr(node.a), b = parseAddr(node.b)
      if (a && b) {
        for (let c = Math.min(a.col, b.col); c <= Math.max(a.col, b.col); c++)
          for (let r = Math.min(a.row, b.row); r <= Math.max(a.row, b.row); r++) out.set(key(c, r), { col: c, row: r })
      }
      break
    }
    case 'bin': refsOf(node.l, out); refsOf(node.r, out); break
    case 'un': case 'paren': refsOf(node.e, out); break
    case 'call': node.args.forEach((x) => refsOf(x, out)); break
  }
}

const sorted = [...cells.values()].sort((x, y) => x.col - y.col || x.row - y.row)

if (mode === 'deps') {
  let o = ''
  for (const c of sorted) {
    let names = []
    if (c.content[0] === '=') {
      const f = parseFormula(c.content.slice(1))
      if (f) {
        const m = new Map()
        refsOf(f.tree, m)
        names = [...m.values()].sort((x, y) => x.col - y.col || x.row - y.row).map((a) => ' ' + key(a.col, a.row))
      }
    }
    o += key(c.col, c.row) + ':' + names.join('') + '\n'
  }
  process.stdout.write(o)
  process.exit(0)
}

// ---------- evaluation ----------
const num = (v) => ({ t: 'num', v })
const err = (v) => ({ t: 'err', v })
const ZERO = num(0)
const memo = new Map()
const active = new Set()

function cellValue(col, row) {
  const k = key(col, row)
  if (memo.has(k)) return memo.get(k)
  const c = cells.get(k)
  if (!c) return ZERO
  if (active.has(k)) return err('#CYCLE!')
  active.add(k)
  const v = evalContent(c.content)
  active.delete(k)
  memo.set(k, v)
  return v
}

const ERRTOK = new Set(['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!'])
function evalContent(s) {
  if (s[0] === '=') {
    const f = parseFormula(s.slice(1))
    if (!f || f.misplaced) return ERR
    return ev(f.tree)
  }
  if (s === '') return ZERO
  if (/^-?\d+(\.\d+)?$/.test(s)) return num(parseFloat(s))
  if (ERRTOK.has(s)) return err(s)
  return { t: 'text', v: s }
}

function toNum(v) {
  if (v.t === 'err') return v
  if (v.t === 'num') return v
  if (v.t === 'bool') return num(v.v ? 1 : 0)
  return err('#VALUE!')
}
const finite = (x) => (Number.isFinite(x) ? num(x) : err('#DIV/0!'))
const rank = { num: 0, text: 1, bool: 2 }
function cpCompare(a, b) {
  const x = Array.from(a), y = Array.from(b)
  for (let i = 0; i < Math.min(x.length, y.length); i++) {
    const d = x[i].codePointAt(0) - y[i].codePointAt(0)
    if (d) return d
  }
  return x.length - y.length
}
function compare(a, b) {
  if (a.t !== b.t) return rank[a.t] - rank[b.t]
  if (a.t === 'text') return cpCompare(a.v, b.v)
  if (a.t === 'bool') return Number(a.v) - Number(b.v)
  return a.v < b.v ? -1 : a.v > b.v ? 1 : 0
}

function refValue(a) {
  const ad = parseAddr(a)
  return ad ? cellValue(ad.col, ad.row) : err('#REF!')
}
function rangeValues(n) {
  const a = parseAddr(n.a), b = parseAddr(n.b)
  if (!a || !b) return [err('#REF!')]
  const out = []
  for (let c = Math.min(a.col, b.col); c <= Math.max(a.col, b.col); c++)
    for (let r = Math.min(a.row, b.row); r <= Math.max(a.row, b.row); r++) out.push(cellValue(c, r))
  return out
}
function argValues(n) {
  if (n.n === 'range') return rangeValues(n)
  return [ev(n)]
}
function single(n) {
  const vs = argValues(n)
  if (vs.length === 1) return vs[0]
  const e = vs.find((v) => v.t === 'err')
  return e || err('#VALUE!')
}

function ev(n) {
  switch (n.n) {
    case 'num': return num(n.v)
    case 'bool': return { t: 'bool', v: n.v }
    case 'paren': return ev(n.e)
    case 'ref': return refValue(n.a)
    case 'range': return ERR
    case 'un': {
      const v = toNum(ev(n.e))
      if (v.t === 'err') return v
      return n.op === '-' ? num(-v.v) : v
    }
    case 'bin': {
      const l = ev(n.l)
      if (['=', '<>', '<', '<=', '>', '>='].includes(n.op)) {
        if (l.t === 'err') return l
        const r = ev(n.r)
        if (r.t === 'err') return r
        const d = compare(l, r)
        const res = { '=': d === 0, '<>': d !== 0, '<': d < 0, '<=': d <= 0, '>': d > 0, '>=': d >= 0 }[n.op]
        return { t: 'bool', v: res }
      }
      const a = toNum(l)
      if (a.t === 'err') return a
      const b = toNum(ev(n.r))
      if (b.t === 'err') return b
      switch (n.op) {
        case '+': return finite(a.v + b.v)
        case '-': return finite(a.v - b.v)
        case '*': return finite(a.v * b.v)
        case '/': return b.v === 0 ? err('#DIV/0!') : finite(a.v / b.v)
        case '^': return finite(Math.pow(a.v, b.v))
      }
      return ERR
    }
    case 'call': return call(n)
  }
  return ERR
}

function call(n) {
  const { name, args } = n
  const multi = ['SUM', 'MIN', 'MAX', 'COUNT', 'AVG']
  if (multi.includes(name)) {
    if (args.length < 1) return ERR
    const vals = args.flatMap(argValues)
    const e = vals.find((v) => v.t === 'err')
    if (e) return e
    if (name === 'COUNT') return num(vals.filter((v) => v.t === 'num').length)
    const nums = []
    for (const v of vals) {
      const x = toNum(v)
      if (x.t === 'err') return x
      nums.push(x.v)
    }
    if (name === 'SUM') return finite(nums.reduce((s, x) => s + x, 0))
    if (name === 'AVG') return finite(nums.reduce((s, x) => s + x, 0) / nums.length)
    if (name === 'MIN') return num(Math.min(...nums))
    return num(Math.max(...nums))
  }
  if (name === 'ABS') {
    if (args.length !== 1) return ERR
    const v = toNum(single(args[0]))
    return v.t === 'err' ? v : num(Math.abs(v.v))
  }
  if (name === 'IF') {
    if (args.length !== 3) return ERR
    const c = single(args[0])
    if (c.t === 'err') return c
    let truth
    if (c.t === 'bool') truth = c.v
    else if (c.t === 'num') truth = c.v !== 0
    else return err('#VALUE!')
    return single(args[truth ? 1 : 2])
  }
  return err('#NAME?')
}

let out = ''
for (const c of sorted) {
  const v = cellValue(c.col, c.row)
  let s
  if (v.t === 'num') s = String(Number(v.v.toPrecision(10)))
  else if (v.t === 'bool') s = v.v ? 'TRUE' : 'FALSE'
  else s = v.v
  out += key(c.col, c.row) + '=' + s + '\n'
}
process.stdout.write(out)
"}

