{"command":"cat > src/cli.js <<'EOF'
import { readFileSync } from 'node:fs'

const mode = process.argv.length === 3 ? process.argv[2] : null
if (mode !== 'replay' && mode !== 'summary') {
  process.stderr.write('error: usage: cli.js replay|summary\n')
  process.exit(2)
}

class Fail extends Error {}
const NAME = /^[A-Za-z0-9_./:-]+$/
const COUNT = /^(0|[1-9][0-9]*)$/

function count(text, field, least) {
  if (!COUNT.test(text) || BigInt(text) < least) throw new Fail(`${field} must be an integer of at least ${least}`)
  return BigInt(text)
}

function makeBucket(p) {
  return {
    name: p.name,
    fresh: () => ({ units: p.capacity * p.per, last: null }),
    advance(s, tick) {
      if (s.last !== null) {
        s.units += p.refill * (tick - s.last)
        const cap = p.capacity * p.per
        if (s.units > cap) s.units = cap
      }
      s.last = tick
    },
    allows: (s) => s.units >= p.per,
    record(s) { s.units -= p.per },
  }
}

function makeWindow(p) {
  return {
    name: p.name,
    fresh: () => ({ ticks: [] }),
    advance(s, tick) {
      const edge = tick - p.span
      s.ticks = s.ticks.filter((t) => t > edge)
    },
    allows: (s) => BigInt(s.ticks.length) < p.limit,
    record(s, tick) { s.ticks.push(tick) },
  }
}

function parse(text) {
  const lines = text.split('\n')
  if (lines.length && lines[lines.length - 1] === '') lines.pop()
  const policies = new Map()
  const routes = new Map()
  const events = []
  let lastTick = null
  lines.forEach((raw, i) => {
    const line = raw.trim()
    if (line === '' || line.startsWith('#')) return
    const w = line.split(/\s+/)
    try {
      const d = w[0]
      const late = () => { if (events.length) throw new Fail('declarations must come before the first event') }
      if (d === 'bucket') {
        if (w.length !== 5) throw new Fail('expected bucket <name> <capacity> <refill> <per>')
        late()
        if (!NAME.test(w[1])) throw new Fail(`invalid policy name ${w[1]}`)
        if (policies.has(w[1])) throw new Fail(`policy ${w[1]} is declared twice`)
        const capacity = count(w[2], 'capacity', 1n)
        const refill = count(w[3], 'refill', 0n)
        const per = count(w[4], 'per', 1n)
        policies.set(w[1], makeBucket({ name: w[1], capacity, refill, per }))
      } else if (d === 'window') {
        if (w.length !== 4) throw new Fail('expected window <name> <limit> <span>')
        late()
        if (!NAME.test(w[1])) throw new Fail(`invalid policy name ${w[1]}`)
        if (policies.has(w[1])) throw new Fail(`policy ${w[1]} is declared twice`)
        const limit = count(w[2], 'limit', 0n)
        const span = count(w[3], 'span', 1n)
        policies.set(w[1], makeWindow({ name: w[1], limit, span }))
      } else if (d === 'route') {
        if (w.length < 3) throw new Fail('expected route <prefix> <policy>...')
        late()
        if (!NAME.test(w[1])) throw new Fail(`invalid route prefix ${w[1]}`)
        if (routes.has(w[1])) throw new Fail(`prefix ${w[1]} is routed twice`)
        const list = w.slice(2).map((n) => {
          if (!policies.has(n)) throw new Fail(`unknown policy ${n}`)
          return policies.get(n)
        })
        routes.set(w[1], list)
      } else if (d === 'event') {
        if (w.length !== 3) throw new Fail('expected event <tick> <key>')
        const tick = count(w[1], 'tick', 0n)
        if (!NAME.test(w[2])) throw new Fail(`invalid key ${w[2]}`)
        if (lastTick !== null && tick < lastTick) throw new Fail(`tick ${tick} is before tick ${lastTick}`)
        lastTick = tick
        events.push({ tick, key: w[2] })
      } else {
        throw new Fail(`unknown directive ${d}`)
      }
    } catch (e) {
      if (e instanceof Fail) throw new Fail(`line ${i + 1}: ${e.message}`)
      throw e
    }
  })
  return { routes, events }
}

function run(text) {
  const { routes, events } = parse(text)
  const states = new Map()
  const results = []
  for (const { tick, key } of events) {
    let best = null
    for (const prefix of routes.keys()) {
      if (key.startsWith(prefix) && (best === null || prefix.length > best.length)) best = prefix
    }
    let denied = null
    if (best !== null) {
      const list = routes.get(best)
      const ss = list.map((p) => {
        const id = p.name + '\0' + key
        if (!states.has(id)) states.set(id, p.fresh())
        return states.get(id)
      })
      list.forEach((p, j) => p.advance(ss[j], tick))
      for (let j = 0; j < list.length; j++) {
        if (!list[j].allows(ss[j])) { denied = list[j].name; break }
      }
      if (denied === null) list.forEach((p, j) => p.record(ss[j], tick))
    }
    results.push({ tick, key, denied })
  }
  return results
}

try {
  const results = run(readFileSync(0, 'utf8'))
  let out = ''
  if (mode === 'replay') {
    for (const r of results) out += `${r.tick} ${r.key} ${r.denied === null ? 'allow' : 'deny ' + r.denied}\n`
  } else {
    const per = new Map()
    let a = 0, d = 0
    for (const r of results) {
      const c = per.get(r.key) || { a: 0, d: 0 }
      if (r.denied === null) { c.a++; a++ } else { c.d++; d++ }
      per.set(r.key, c)
    }
    for (const k of [...per.keys()].sort((x, y) => (x < y ? -1 : x > y ? 1 : 0))) {
      out += `${k} allowed=${per.get(k).a} denied=${per.get(k).d}\n`
    }
    out += `total allowed=${a} denied=${d}\n`
  }
  process.stdout.write(out)
} catch (e) {
  if (!(e instanceof Fail)) throw e
  process.stderr.write(`error: ${e.message}\n`)
  process.exit(2)
}
EOF
