import { readFileSync } from 'node:fs'

const mode = process.argv.length === 3 ? process.argv[2] : null
function fail(msg) {
  process.stderr.write(msg + '\n')
  process.exit(2)
}
if (mode !== 'rounds' && mode !== 'tally') fail('error: usage: cli.js rounds|tally')

const lines = readFileSync(0, 'utf8').split('\n')
if (lines[lines.length - 1] === '') lines.pop()

let candidates = null
const ballots = []
const NAME = /^[A-Za-z0-9_-]+$/
for (let i = 0; i < lines.length; i++) {
  const n = i + 1
  const line = lines[i].trim()
  if (line === '' || line.startsWith('#')) continue
  const t = line.split(/\s+/)
  const word = t[0]
  if (word === 'candidates') {
    if (candidates !== null || ballots.length > 0) fail(`error: line ${n}: candidates must be declared once, before any ballot`)
    if (t.length < 2) fail(`error: line ${n}: expected candidates <name>...`)
    const seen = new Set()
    for (const name of t.slice(1)) {
      if (!NAME.test(name)) fail(`error: line ${n}: invalid candidate name ${name}`)
      if (seen.has(name)) fail(`error: line ${n}: candidate ${name} is declared twice`)
      seen.add(name)
    }
    candidates = t.slice(1)
  } else if (word === 'ballot') {
    if (candidates === null) fail(`error: line ${n}: candidates must be declared once, before any ballot`)
    if (t.length < 3) fail(`error: line ${n}: expected ballot <count> <candidate>...`)
    if (!/^[1-9][0-9]*$/.test(t[1])) fail(`error: line ${n}: count must be a positive integer`)
    const seen = new Set()
    for (const name of t.slice(2)) {
      if (!candidates.includes(name)) fail(`error: line ${n}: unknown candidate ${name}`)
      if (seen.has(name)) fail(`error: line ${n}: candidate ${name} is repeated`)
      seen.add(name)
    }
    ballots.push({ count: BigInt(t[1]), prefs: t.slice(2) })
  } else {
    fail(`error: line ${n}: unknown directive ${word}`)
  }
}
if (candidates === null) fail('error: no candidates')

const cont = new Set(candidates)
const history = []
const out = []
let winner = null
const cmp = (a, b) => (a < b ? -1 : a > b ? 1 : 0)
for (;;) {
  const counts = new Map([...cont].map((c) => [c, 0n]))
  let active = 0n
  for (const b of ballots) {
    const c = b.prefs.find((p) => cont.has(p))
    if (c !== undefined) {
      counts.set(c, counts.get(c) + b.count)
      active += b.count
    }
  }
  history.push(counts)
  const total = ballots.reduce((s, b) => s + b.count, 0n)
  const list = [...counts.entries()].sort((a, b) => cmp(b[1], a[1]) || cmp(a[0], b[0]))
  let text = `round ${history.length}: ` + list.map(([c, v]) => `${c}=${v}`).join(' ') + ` exhausted=${total - active}`
  out.push(text)
  if (active === 0n) break
  const top = list.find(([, v]) => v * 2n > active)
  if (top) { winner = top[0]; break }
  let min = list[list.length - 1][1]
  let tied = list.filter(([, v]) => v === min).map(([c]) => c)
  for (let again = tied.length > 1; again;) {
    again = false
    for (const h of history) {
      const vals = tied.map((c) => h.get(c))
      const m = vals.reduce((a, b) => (b < a ? b : a))
      if (vals.some((v) => v !== m)) {
        tied = tied.filter((c) => h.get(c) === m)
        again = tied.length > 1
        break
      }
    }
  }
  const elim = tied.sort().pop()
  cont.delete(elim)
  out.push(`eliminated ${elim}`)
}
const end = winner === null ? 'no winner' : `winner ${winner}`
if (mode === 'tally') process.stdout.write(`rounds ${history.length}\n${end}\n`)
else process.stdout.write(out.join('\n') + '\n' + end + '\n')
EOF
