  const s = lines[i].replace(/^[ \t]+/, '')
  if (s === '' || s[0] === '#') continue
  const m = /^[^ \t]*/.exec(s)
  const addr = m[0]
  const rest = s.slice(addr.length).replace(/^[ \t]+/, '')
  const am = /^([A-Za-z]{1,2})([0-9]{1,3})$/.exec(addr)
  if (!am || Number(am[2]) < 1) {
    process.stderr.write(`error: line ${i + 1}: invalid cell address ${addr}\n`)
    process.exit(2)
  }
  const key = am[1].toUpperCase() + Number(am[2])
  if (cells.has(key)) {
    process.stderr.write(`error: line ${i + 1}: cell ${addr} is declared twice\n`)
    process.exit(2)
  }
  cells.set(key, { col: colIndex(am[1].toUpperCase()), row: Number(am[2]), content: rest, key })
}

const sorted = [...cells.values()].sort((a, b) => a.col - b.col || a.row - b.row)
