const NAME = /^[A-Za-z0-9_-]+$/
const COUNT = /^[1-9][0-9]*$/

function bad(msg) { const e = new Error(msg); e.userMessage = msg; return e }

export function parse(text) {
  const lines = text.split('\n')
  if (lines.length && lines[lines.length - 1] === '') lines.pop()
  let candidates = null
  const ballots = []
  for (let i = 0; i < lines.length; i++) {
    const n = i + 1
    const line = lines[i].trim()
    if (line === '' || line.startsWith('#')) continue
    const t = line.split(/\s+/)
    const err = (m) => bad(`error: line ${n}: ${m}`)
    if (t[0] === 'candidates') {
      if (candidates !== null) throw err('candidates must be declared once, before any ballot')
      if (t.length < 2) throw err('expected candidates <name>...')
      const seen = new Set()
      for (const name of t.slice(1)) {
        if (!NAME.test(name)) throw err(`invalid candidate name ${name}`)
        if (seen.has(name)) throw err(`candidate ${name} is declared twice`)
        seen.add(name)
      }
      candidates = t.slice(1)
    } else if (t[0] === 'ballot') {
      if (candidates === null) throw err('candidates must be declared once, before any ballot')
      if (t.length < 3) throw err('expected ballot <count> <candidate>...')
      if (!COUNT.test(t[1])) throw err('count must be a positive integer')
      const seen = new Set()
      for (const name of t.slice(2)) {
        if (!candidates.includes(name)) throw err(`unknown candidate ${name}`)
        if (seen.has(name)) throw err(`candidate ${name} is repeated`)
        seen.add(name)
      }
      ballots.push({ count: BigInt(t[1]), prefs: t.slice(2) })
    } else {
      throw err(`unknown directive ${t[0]}`)
    }
  }
  if (candidates === null) throw bad('error: no candidates')
  return { candidates, ballots }
}
EOF
cat > src/count.js <<'EOF'
export function count({ candidates, ballots }, mode) {
  const continuing = new Set(candidates)
  const history = new Map(candidates.map((c) => [c, []]))
  const out = []
  let round = 0
  let result
  for (;;) {
    round++
    const votes = new Map([...continuing].map((c) => [c, 0n]))
    let active = 0n
    for (const b of ballots) {
      const c = b.prefs.find((p) => continuing.has(p))
      if (c !== undefined) { votes.set(c, votes.get(c) + b.count); active += b.count }
    }
    const total = ballots.reduce((s, b) => s + b.count, 0n)
    for (const [c, v] of votes) history.get(c).push(v)
    const order = [...votes.keys()].sort((a, b) => {
      const d = votes.get(b) - votes.get(a)
      if (d !== 0n) return d > 0n ? 1 : -1
      return a < b ? -1 : a > b ? 1 : 0
    })
    let line = `round ${round}: ` + order.map((c) => `${c}=${votes.get(c)}`).join(' ')
    line += ` exhausted=${total - active}`
    out.push(line)
    if (active === 0n) { result = 'no winner'; break }
    const win = order.find((c) => votes.get(c) * 2n > active)
    if (win !== undefined) { result = `winner ${win}`; break }
    let min = votes.get(order[order.length - 1])
    let tied = order.filter((c) => votes.get(c) === min)
    for (let r = 0; tied.length > 1 && r < round; ) {
      const vs = tied.map((c) => history.get(c)[r])
      const m = vs.reduce((a, b) => (b < a ? b : a))
      if (vs.every((v) => v === m)) { r++; continue }
      tied = tied.filter((c) => history.get(c)[r] === m)
      r = 0
    }
    const elim = tied.reduce((a, b) => (b > a ? b : a))
    continuing.delete(elim)
    out.push(`eliminated ${elim}`)
  }
  if (mode === 'tally') return `rounds ${round}\n${result}\n`
  return out.join('\n') + '\n' + result + '\n'
}
EOF
