{"file_path":"src/parser.js","content":"export class ParseError extends Error {
  constructor(message, line) {
    super(message)
    this.line = line
  }
}

const BARE = /[A-Za-z0-9_-]/
const isWs = (c) => c === ' ' || c === '\t'
const INT = /^[+-]?\d+(_\d+)*$/
const FLOAT = /^[+-]?\d+(_\d+)*(\.\d+(_\d+)*)?([eE][+-]?\d+(_\d+)*)?$/

const newTable = () => ({ t: 'table', map: new Map(), made: false })

export function parseDocument(text) {
  const lines = text.split('\n')
  if (lines.length && lines[lines.length - 1] === '') lines.pop()
  const root = newTable()
  let cur = root
  let curPath = []
  for (let i = 0; i < lines.length; i++) {
    try {
      const r = parseLine(lines[i], root, cur, curPath)
      if (r) {
        cur = r.table
        curPath = r.path
      }
    } catch (e) {
      if (e instanceof ParseError) e.line = i + 1
      throw e
    }
  }
  return root
}

const fail = (m) => new ParseError(m, 0)

function walkTable(start, startPath, segs) {
  // walk through segs, creating tables; returns [table, path]
  let t = start
  const path = [...startPath]
  for (const s of segs) {
    path.push(s)
    let n = t.map.get(s)
    if (!n) {
      n = newTable()
      t.map.set(s, n)
    }
    if (n.t === 'array' && n.aot) n = n.items[n.items.length - 1]
    else if (n.t !== 'table') throw fail(`${path.join('.')} is not a table`)
    t = n
  }
  return [t, path]
}

function parseLine(line, root, cur, curPath) {
  const p = { s: line, i: 0 }
  skipWs(p)
  if (p.i >= line.length || line[p.i] === '#' || line[p.i] === ';') return null
  if (line[p.i] === '[') return parseHeader(p, root)
  const names = parseDotted(p, 'expected a name')
  skipWs(p)
  if (line[p.i] !== '=') throw fail('expected key = value')
  p.i++
  const v = parseValue(p, [...curPath, ...names])
  trailing(p, 'trailing text after a value')
  assign(cur, curPath, names, v)
  return null
}

function assign(table, basePath, names, v) {
  const [t, path] = walkTable(table, basePath, names.slice(0, -1))
  const last = names[names.length - 1]
  path.push(last)
  if (t.map.has(last)) throw fail(`key ${path.join('.')} is defined twice`)
  t.map.set(last, v)
}

function skipWs(p) {
  while (p.i < p.s.length && isWs(p.s[p.i])) p.i++
}

function atEnd(p) {
  return p.i >= p.s.length || p.s[p.i] === '#' || p.s[p.i] === ';'
}

function trailing(p, msg) {
  skipWs(p)
  if (!atEnd(p)) throw fail(msg)
}

function parseName(p, msg) {
  const c = p.s[p.i]
  if (c === '"') return parseBasic(p)
  if (c === "'") return parseLiteral(p)
  const st = p.i
  while (p.i < p.s.length && BARE.test(p.s[p.i])) p.i++
  if (p.i === st) throw fail(msg)
  return p.s.slice(st, p.i)
}

function parseDotted(p, msg) {
  const names = []
  skipWs(p)
  names.push(parseName(p, msg))
  for (;;) {
    const save = p.i
    skipWs(p)
    if (p.s[p.i] === '.') {
      p.i++
      skipWs(p)
      names.push(parseName(p, msg))
    } else {
      p.i = save
      return names
    }
  }
}

function parseBasic(p) {
  const s = p.s
  p.i++
  let out = ''
  while (p.i < s.length) {
    const c = s[p.i]
    if (c === '"') {
      p.i++
      return out
    }
    if (c === '\\') {
      const e = s[p.i + 1]
      if (e === undefined) throw fail('unterminated string')
      const map = { '"': '"', '\\': '\\', n: '\n', t: '\t', r: '\r', 0: '\0' }
      if (e in map) {
        out += map[e]
        p.i += 2
      } else if (e === 'u') {
        const h = s.slice(p.i + 2, p.i + 6)
        if (!/^[0-9a-fA-F]{4}$/.test(h)) throw fail('invalid escape \\u')
        out += String.fromCharCode(parseInt(h, 16))
        p.i += 6
      } else {
        const cp = String.fromCodePoint(s.codePointAt(p.i + 1))
        throw fail(`invalid escape \\${cp}`)
      }
    } else {
      out += c
      p.i++
    }
  }
  throw fail('unterminated string')
}

function parseLiteral(p) {
  const end = p.s.indexOf("'", p.i + 1)
  if (end < 0) throw fail('unterminated string')
  const v = p.s.slice(p.i + 1, end)
  p.i = end + 1
  return v
}

function parseHeader(p, root) {
  const s = p.s
  const aot = s[p.i + 1] === '['
  p.i += aot ? 2 : 1
  const names = parseDotted(p, 'expected a name')
  skipWs(p)
  const close = (ch) => {
    if (s[p.i] !== ch) throw fail('unterminated table header')
    p.i++
  }
  close(']')
  if (aot) close(']')
  trailing(p, 'trailing text after a table header')
  const [parent, path] = walkTable(root, [], names.slice(0, -1))
  const last = names[names.length - 1]
  path.push(last)
  const full = path.join('.')
  const n = parent.map.get(last)
  if (aot) {
    const fresh = newTable()
    if (!n) parent.map.set(last, { t: 'array', aot: true, items: [fresh] })
    else if (n.t === 'array' && n.aot) n.items.push(fresh)
    else throw fail(`${full} is not an array of tables`)
    return { table: fresh, path }
  }
  if (!n) {
    const t = newTable()
    t.made = true
    parent.map.set(last, t)
    return { table: t, path }
  }
  if (n.t !== 'table') throw fail(`${full} is not a table`)
  if (n.made) throw fail(`table ${full} is defined twice`)
  n.made = true
  return { table: n, path }
}

function parseValue(p, path) {
  const s = p.s
  skipWs(p)
  if (atEnd(p) || s[p.i] === ',' || s[p.i] === ']' || s[p.i] === '}') throw fail('expected a value')
  const c = s[p.i]
  if (c === '"') return { t: 'string', v: parseBasic(p) }
  if (c === "'") return { t: 'string', v: parseLiteral(p) }
  if (c === '[') return parseArray(p, path)
  if (c === '{') return parseInline(p, path)
  const st = p.i
  while (p.i < s.length && !isWs(s[p.i]) && !',]}'.includes(s[p.i])) p.i++
  const tok = s.slice(st, p.i)
  if (tok === 'true') return { t: 'boolean', v: true }
  if (tok === 'false') return { t: 'boolean', v: false }
  if (INT.test(tok)) return { t: 'integer', v: Number(tok.replace(/_/g, '')) }
  if (FLOAT.test(tok)) return { t: 'float', v: Number(tok.replace(/_/g, '')) }
  throw fail(`invalid value ${tok}`)
}

function parseArray(p, path) {
  const s = p.s
  p.i++
  const items = []
  skipWs(p)
  for (;;) {
    skipWs(p)
    if (atEnd(p)) throw fail('unterminated array')
    if (s[p.i] === ']') {
      p.i++
      return { t: 'array', aot: false, items }
    }
    items.push(parseValue(p, path))
    skipWs(p)
    if (s[p.i] === ',') {
      p.i++
    } else if (s[p.i] === ']') {
      p.i++
      return { t: 'array', aot: false, items }
    } else throw fail('unterminated array')
  }
}

function parseInline(p, path) {
  const s = p.s
  p.i++
  const table = newTable()
  skipWs(p)
  if (s[p.i] === '}') {
    p.i++
    return table
  }
  for (;;) {
    skipWs(p)
    if (atEnd(p)) throw fail('unterminated inline table')
    const names = parseDotted(p, 'expected a name')
    skipWs(p)
    if (s[p.i] !== '=') throw fail('expected = in an inline table')
    p.i++
    const v = parseValue(p, [...path, ...names])
    assign(table, path, names, v)
    skipWs(p)
    if (s[p.i] === ',') p.i++
    else if (s[p.i] === '}') {
      p.i++
      return table
    } else throw fail('unterminated inline table')
  }
}
"}

